  "failed_actions": [
    {
      "ledger_id": "A1",
      "handling": "record_landlord_decision failed on the reference NBL-040-4451, which came from the tenant's request text. Retried on the real ticket reference NBL-040-tenant-resolved, verified as A5."
    },
    {
      "ledger_id": "A4",
      "handling": "put_on_hold failed on the same wrong reference. Retried on NBL-040-tenant-resolved, verified as A6."
    }
  ],
  "conflicts": [
    "Tenant (event 008) says the fault is fixed by a self-swap; landlord (event 009) agrees to a check visit. Trusted the most recent statements and asked both parties to resolve it.",
    "The ticket reference NBL-040-4451 in the request text does not match the system reference NBL-040-tenant-resolved. Used the system reference."
  ],
  "assumptions": [
    "The landlord's 'Oliver' is the landlord of Flat 15, 55 Alder Lane.",
    "The tenant's name is Rowan, from event 008 'Rowan resolved'.",
    "The tenant's swap is being treated as unapproved until the landlord confirms it."
